setup:
$src = "$env:PASEO_SOURCE_CHECKOUT_PATH\.venv"
if (Test-Path $src) {
  robocopy $src ".venv" /E /NFL /NDL /NJH /NJS /NP /MT:16 | Out-Null
  if ($LASTEXITCODE -ge 8) { Write-Host "[setup] .venv 复制失败 rc=$LASTEXITCODE"; exit 1 }
} else {
  py -3.12 -m venv .venv
  if ($LASTEXITCODE -ne 0) { Write-Host "[setup] venv 创建失败"; exit 1 }
  & ".venv\Scripts\python.exe" -m pip install -q -r trader\requirements-ci.txt
  if ($LASTEXITCODE -ne 0) { Write-Host "[setup] 依赖安装失败"; exit 1 }
  & ".venv\Scripts\python.exe" -m pip install -q numpy pandas matplotlib seaborn python-dotenv uvicorn psutil
  if ($LASTEXITCODE -ne 0) { Write-Host "[setup] 补充依赖安装失败"; exit 1 }
}
exit 0

$nm = "$env:PASEO_SOURCE_CHECKOUT_PATH\Frontend\node_modules"
if (Test-Path $nm) {
  robocopy $nm "Frontend\node_modules" /E /NFL /NDL /NJH /NJS /NP /MT:16 | Out-Null
  if ($LASTEXITCODE -ge 8) { Write-Host "[setup] node_modules 复制失败 rc=$LASTEXITCODE"; exit 1 }
} else {
  npm --prefix Frontend ci --no-audit --no-fund
  if ($LASTEXITCODE -ne 0) { Write-Host "[setup] npm ci 失败"; exit 1 }
}
exit 0

& ".venv\Scripts\python.exe" -c "import sys; print('[setup] python', sys.version.split()[0])"
if ($LASTEXITCODE -ne 0) { exit 1 }
exit 0
